    "skill": "Boundaries",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "Although there was no contact between Japan and Britain during the prehistoric era, there are surprising parallels between them. In both places, inhabitants built stone circles, crafted elaborate pots, and used flaked stone tools. Furthermore, the ______ bear striking similarities to the circle at Stonehenge.",
