    "explanation": "The four choices are the same words. They differ only in what comes after \"factor\": A a comma, B a semicolon, C nothing, D a comma. Use a colon when the part before is a complete independent clause AND what follows explains, illustrates, or lists. The part after does NOT have to be a complete sentence. Ask: Cover what comes after the colon. Is what remains a complete sentence? If yes, colon is OK. If no, eliminate it. The answer is D, \"factor, however:\".",
