    "difficulty": "Easy",
    "ruleType": "NoPunct",
    "passage": "The capital city of the Aztec empire, Tenochtitlan, was built on an island in a lake. Because of the marshy conditions, the Aztec people ______ floating farms called “chinampas.”",
