    "difficulty": "Medium",
    "ruleType": "VTense",
    "passage": "The alga species Chlorella vulgaris is very efficient at making oxygen. For this reason, scientists are currently exploring ways to use this species in space. C. vulgaris might be used, for example, to build future biological air exchange systems that ______ oxygen for astronauts.",
    "question": "Which choice completes the text so that it conforms to the conventions of Standard English?",
